package cn.bidcheck.verification.engine;

import cn.bidcheck.domain.Domain.Document;
import cn.bidcheck.domain.Domain.Page;
import cn.bidcheck.domain.Domain.Checkpoint;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.Test;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import static cn.bidcheck.verification.engine.VerificationTypes.*;
import static org.junit.jupiter.api.Assertions.*;

class VerificationEngineTest {
    final ObjectMapper json=new ObjectMapper();
    static Document doc(String text){return new Document("bid","p","BID","投标.pdf",1,"sha","",List.of(new Page(1,text,"PAGE","PDF","")),List.of());}
    static Rule rule(String predicate,String subject,String field,String expected,Map<String,Object> params){return new Rule("O1","测试条件",predicate,subject,field,">=",expected,"",params,"真实要求","",List.of());}
    static Fact fact(String kind,String subject,String field,String value,String unit,String basis,Map<String,Object> attrs,EvidenceCorpus corpus){return new Fact("f"+value,kind,subject,field,value,value,unit,basis,"CURRENT_PROJECT",List.of(corpus.all.get(0).id()),attrs);}
    static RuleEvaluator evaluator(EvidenceCorpus c,List<Fact> f){return new RuleEvaluator(f,c,Map.of());}
    @Test void emptyAllAndAnyNeverPass(){for(String logic:List.of("ALL","ANY"))assertEquals("UNDETERMINED",RuleEvaluator.combine("id","text",logic,List.of()).status());}
    @Test void anyWithUnknownAlternativeCannotFail(){Decision fail=new Decision("a","","FAIL","",List.of(),List.of(),Map.of());Decision unknown=new Decision("b","","UNDETERMINED","",List.of(),List.of(gap("INPUT","missing")),Map.of());assertEquals("UNDETERMINED",RuleEvaluator.combine("id","","ANY",List.of(fail,unknown)).status());}
    @Test void anyCompleteProofMayPassWithoutUnneededBranch(){Decision pass=new Decision("a","","PASS","",List.of(),List.of(),Map.of());Decision unknown=new Decision("b","","UNDETERMINED","",List.of(),List.of(gap("INPUT","missing")),Map.of());Decision result=RuleEvaluator.combine("id","","ANY",List.of(pass,unknown));assertEquals("PASS",result.status());assertTrue(result.gaps().isEmpty());}
    @Test void emptyForeachDoesNotProvePopulation(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("人员资料")));Rule r=new Rule("a","全部成员","","","","","","",Map.of(),"全体成员","FOR_EACH",List.of(rule("MATERIAL","","","证书",Map.of())));assertEquals("UNDETERMINED",evaluator(c,List.of()).evaluate(r).status());}
    @Test void decimalPointAndTableWhitespacePreserved(){assertFalse(ProofVerifier.numberPresent("总价 123 万元","12.3"));assertTrue(ProofVerifier.numberPresent("金额 1,234.50 万元","1234.50"));assertTrue(ProofVerifier.numberPresent("序号 1 335.06 单价 20","335.06"));assertFalse(ProofVerifier.numberPresent("序号 1 335.06","1335.06"));}
    @Test void quotedAmountCannotBorrowAnotherBasis(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("总工程造价：1335.06万元。建安费用：200万元。")));Fact f=fact("NUMBER","合同","amount","1335.06","万元","建安费用",Map.of(),c);assertNotNull(new ProofVerifier().issue(f,c.byId));}
    @Test void modelCannotCiteUnknownSource()throws Exception{EvidenceCorpus c=new EvidenceCorpus(List.of(doc("金额：12元")));var result=new ProofVerifier().verify(json.readTree("{\"facts\":[{\"kind\":\"NUMBER\",\"rawValue\":\"12\",\"sourceIds\":[\"foreign\"]}]}"),c.all);assertTrue(result.facts().isEmpty());assertEquals("SOURCE_REFERENCE_INVALID",result.rejected().get(0).get("code"));}
    @Test void directoryDoesNotProveSection(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("目录\n技术方案……20\n施工进度……30\n")));Fact f=fact("SECTION","","","技术方案","","",Map.of(),c);assertEquals("NAVIGATION_NOT_SUBSTANTIVE",new ProofVerifier().issue(f,c.byId));}
    @Test void disjointMonthsCannotProveContinuity(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("参保人：测试甲 2025年1月 2025年3月 2025年5月")));Fact f=fact("MONTHS","测试甲","","社保","","",Map.of("person","测试甲","months",List.of("2025-01","2025-03","2025-05")),c);assertEquals("UNDETERMINED",evaluator(c,List.of(f)).evaluate(rule("MONTHS","测试甲","","",Map.of("count",3,"earliestMonth","2024-12"))).status());}
    @Test void optionalWindowDoesNotRequireFirstMonth(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("社保：2025年1月 2025年2月 2025年3月")));Fact f=fact("MONTHS","甲","","社保","","",Map.of("months",List.of("2025-01","2025-02","2025-03")),c);assertEquals("PASS",evaluator(c,List.of(f)).evaluate(rule("MONTHS","甲","","",Map.of("count",3,"earliestMonth","2024-12"))).status());}
    @Test void expiredCertificateAndUnconfirmedTimeRemainDistinct(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("姓名：甲 注册证书 证书编号：R001 有效期2024年1月1日至2025年1月1日")));Fact f=fact("CERTIFICATE","甲","","注册证书","","",Map.of("category","注册证书","number","R001","numberField","证书编号","validityField","有效期","start","2024-01-01","end","2025-01-01"),c);Rule r=rule("VALIDITY","甲","有效期","",Map.of("category","注册证书","validityField","有效期"));assertEquals("UNDETERMINED",evaluator(c,List.of(f)).evaluate(r).status());Map<String,Object> ctx=new HashMap<>(Map.of("referenceDate","2025-08-01","referenceDateSource","t","referenceDateSourceVerified",true,"referenceDateEvidence",Map.of("documentId","t","quote","投标截止2025年8月1日","confirmation","USER_SELECTED_VERSION")));assertEquals("FAIL",new RuleEvaluator(List.of(f),c,ctx).evaluate(r).status());}
    @Test void relationshipNeedsBothEndpoints(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("甲公司承担设计工作。")));Fact f=fact("RELATION","测试甲","所属单位","","","",Map.of("object","甲公司"),c);assertEquals("RAW_VALUE_UNGROUNDED",new ProofVerifier().issue(f,c.byId));}
    @Test void graphTraversesOnlySourcedOrderedEdges(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("测试甲所属甲公司，甲公司负责设计")));Fact a=fact("RELATION","测试甲","所属单位","甲公司","","",Map.of("object","甲公司"),c),b=fact("RELATION","甲公司","负责","设计","","",Map.of("object","设计"),c);Rule r=rule("RELATION","测试甲","","设计",Map.of("path",List.of("所属单位","负责")));assertEquals("PASS",evaluator(c,List.of(a,b)).evaluate(r).status());assertEquals("UNDETERMINED",evaluator(c,List.of(b)).evaluate(r).status());}
    @Test void unsupportedTaxOrAmountBasisDoesNotPass(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("合同总价500万元")));Fact f=fact("CONTRACT","X","","合同总价500万元","","",Map.of("contractName","测试合同","amount","500","unit","万元","amountBasis","总价"),c);Rule r=new Rule("r","建安费要求","CONTRACT","","","","","万元",Map.of("amountMinimum",200,"amountBasis","建安费"),"建安费至少200万元","",List.of());assertEquals("UNDETERMINED",evaluator(c,List.of(f)).evaluate(r).status());}
    @Test void contractScoreDeduplicatesSameContract(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("合同编号ABC，金额100万元")));Fact f=fact("CONTRACT","ABC","","合同","","",Map.of("contractNumber","ABC","contractName","工程合同","party","甲公司"),c);Fact duplicate=new Fact("copy",f.kind(),f.subject(),f.field(),f.rawValue(),f.value(),f.unit(),f.basis(),f.scope(),f.sourceIds(),f.attributes());Rule r=new Rule("score","每项2分","SCORE_COUNT","","","","","",Map.of("pointsPerItem",2,"maxScore",10),"每项2分最多10分","ALL",List.of(rule("CONTRACT","","","",Map.of())));Decision out=new RuleEvaluator(List.of(f,duplicate),c,Map.of("contractSetComplete",true)).evaluate(r);assertEquals("PASS",out.status());assertEquals("2",out.proof().get("score").toString());}
    @Test void importedExternalRecordIsNotTrusted(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("我们承诺无禁入记录")));Map<String,Object> ctx=Map.of("externalRecords",List.of(Map.of("type","blacklist","subject","甲","provenanceStatus","PROVIDED_NOT_AUTHENTICATED","result","PASS")));assertEquals("UNDETERMINED",new RuleEvaluator(List.of(),c,ctx).evaluate(rule("EXTERNAL","甲","blacklist","false",Map.of())).status());}
    @Test void validTrustedExternalFieldCanCloseAtomicRequirement(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("甲单位资料")));Map<String,Object> record=linked("id","e","type","BLACKLIST","subject","甲","provenanceStatus","TRUSTED_CONNECTOR","rawSnapshotHash","hash","source","official","queriedAt","2025-08-01T10:00:00Z","coverageComplete",true,"result",Map.of("status","VERIFIED","facts",List.of(Map.of("field","listed","value","false","rawValue","未列入","sourceQuote","甲：未列入"))));Rule r=new Rule("r","名单核查","EXTERNAL","甲","listed","=","false","",Map.of("externalType","BLACKLIST"),"甲不在禁入名单","",List.of());assertEquals("PASS",new RuleEvaluator(List.of(),c,Map.of("externalRecords",List.of(record))).evaluate(r).status());}
    @Test void foreignProjectRejectedBeforeModel(){VerificationEngine e=new VerificationEngine();Document foreign=new Document("b2","foreign","BID","",1,"sha2","",List.of(),List.of());assertThrows(IllegalArgumentException.class,()->e.evaluate(cp(),List.of(doc("文字"),foreign),null,Map.of()));}
    static Checkpoint cp(){return new Checkpoint("c","承诺书提交","组成","一般","SEMANTIC_RESPONSE","","","提交守法承诺书","",true,true,true,null);}
    @Test void completedPaidStepsResumeAndInputChangeInvalidatesExtraction()throws Exception{
        AtomicInteger calls=new AtomicInteger();ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "test-model-v1";}public JsonNode request(String op,Map<String,Object> input){calls.incrementAndGet();if(op.equals("COMPILE"))return json.valueToTree(Map.of("logic","ALL","rules",List.of(Map.of("id","O1","predicate","DECLARATION","description","提交守法承诺书","expected","守法承诺书","sourceQuote","提交守法承诺书"))));List<Map<String,Object>> sources=(List<Map<String,Object>>)input.get("sources");return json.valueToTree(Map.of("facts",List.of(Map.of("kind","DECLARATION","rawValue","守法承诺书","value","守法承诺书","scope","CURRENT_PROJECT","sourceIds",List.of(sources.get(0).get("id"))))));}};
        VerificationEngine engine=new VerificationEngine(gateway,null);Document d=doc("守法承诺书\n我们承诺遵守法律并承担相关责任。相关义务按照本项目招标要求履行，所有声明均由本公司出具。声明正文结束。");Map<String,Object> first=engine.evaluate(cp(),List.of(d),null,Map.of());assertEquals("PASS",first.get("businessDecision"));int initial=calls.get();Map<String,Object> second=engine.evaluate(cp(),List.of(d),null,Map.of("priorSteps",first.get("steps")));assertEquals("PASS",second.get("businessDecision"));assertEquals(initial,calls.get());
        Document changed=new Document(d.id(),d.projectId(),d.role(),d.name(),2,"newHash","",d.pages(),d.warnings());engine.evaluate(cp(),List.of(changed),null,Map.of("priorSteps",first.get("steps"),"maxModelCalls",8));assertEquals(initial+1,calls.get());}
    @Test void failedAttemptsConsumePersistentBudget()throws Exception{AtomicInteger calls=new AtomicInteger();ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "fail";}public JsonNode request(String op,Map<String,Object> input)throws IOException{calls.incrementAndGet();throw new IOException("network");}};List<Map<String,Object>> saved=new ArrayList<>();Map<String,Object> ctx=new HashMap<>();ctx.put("maxModelCalls",1);ctx.put("stepObserver",(Consumer<Map<String,Object>>)saved::add);RunSession first=new RunSession(gateway,ctx,"doc");assertThrows(IOException.class,()->first.model("EXTRACT",Map.of("data","x")));RunSession retry=new RunSession(gateway,Map.of("maxModelCalls",1,"priorSteps",saved),"doc");assertThrows(IOException.class,()->retry.model("EXTRACT",Map.of("data","x")));assertEquals(1,calls.get());}
    @Test void leaseObserverFailureStopsBeforePaidCall(){AtomicInteger calls=new AtomicInteger();ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "test";}public JsonNode request(String op,Map<String,Object> input){calls.incrementAndGet();return json.createObjectNode();}};RunSession s=new RunSession(gateway,Map.of("stepObserver",(Consumer<Map<String,Object>>)m->{throw new IllegalStateException("lease lost");}),"scope");assertThrows(IllegalStateException.class,()->s.model("EXTRACT",Map.of()));assertEquals(0,calls.get());}
    @Test void modelCannotInventCompiledAmountThreshold()throws Exception{ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "compile";}public JsonNode request(String o,Map<String,Object> i){return json.valueToTree(Map.of("logic","ALL","rules",List.of(Map.of("id","a","predicate","CONTRACT","sourceQuote","金额不少于200万元","parameters",Map.of("amountMinimum",20)))));}};Checkpoint c=new Checkpoint("c","业绩","评分","","SEMANTIC_RESPONSE","","","金额不少于200万元","",true,true,true,null);Plan p=new RequirementCompiler().compile(c,new RunSession(gateway,Map.of(),"s"));assertEquals(1,p.rules().size());assertEquals("UNSUPPORTED",p.rules().get(0).predicate());assertEquals("金额不少于200万元",p.rules().get(0).sourceQuote());assertTrue(p.rules().get(0).parameters().containsKey("compilationIssue"));assertFalse(p.issues().isEmpty());assertEquals("UNDETERMINED",new RuleEvaluator(List.of(),new EvidenceCorpus(List.of(doc("业绩材料"))),Map.of()).evaluate(p.rules().get(0)).status());}
    @Test void droppedIndependentObligationIsCompileGap(){Rule declaration=new Rule("a","提交承诺","DECLARATION","","","","承诺书","",Map.of(),"提交承诺书；项目经理须具备注册证书","",List.of());assertFalse(RequirementCoverage.issues("提交承诺书；项目经理须具备注册证书",List.of(declaration)).isEmpty());}
    @Test void layoutCannotBorrowLabelFromDifferentAmountRow(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("建安费用 500 万元 总价 900 万元")));Fact f=fact("NUMBER","合同","amount","900","万元","建安费用",Map.of("cellIds",List.of("a","b")),c);List<Map<String,Object>> cells=List.of(linked("cellId","a","spanId","sa","documentId","bid","location",1,"tableId","t","row",1,"column",1,"text","建安费用"),linked("cellId","b","spanId","sb","documentId","bid","location",1,"tableId","t","row",2,"column",2,"text","900 万元"));assertFalse(LayoutBinding.amount(f,cells,c.byId));}
    @Test void sameRowLayoutCanBindSplitColumns(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("建安费用\n"+"说明内容".repeat(50)+"\n500 万元")));Fact f=fact("NUMBER","合同","amount","500","万元","建安费用",Map.of("cellIds",List.of("a","b")),c);List<Map<String,Object>> cells=List.of(linked("cellId","a","spanId","sa","documentId","bid","location",1,"tableId","t","row",1,"column",1,"text","建安费用"),linked("cellId","b","spanId","sb","documentId","bid","location",1,"tableId","t","row",1,"column",2,"text","500 万元"));assertTrue(LayoutBinding.amount(f,cells,c.byId));}
    @Test void childHeadingDoesNotEndParentSection(){String body="1 技术方案\n"+"具体技术措施及资源配置说明。".repeat(60)+"\n1.1 安装措施\n"+"安装流程和质量控制说明。".repeat(90)+"\n2 项目管理\n管理计划";EvidenceCorpus c=new EvidenceCorpus(List.of(doc(body)));Fact section=fact("SECTION","","","技术方案","","",Map.of(),c);assertFalse(SectionCoverage.covered(section,c,List.of(c.all.get(0))));assertTrue(SectionCoverage.covered(section,c,c.all));}
    @Test void nativeMaterialDoesNotManufactureOtherMemberSubject(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("守法承诺书\n甲公司承诺依法履约。"+"承诺事项均依法进行。".repeat(8))));assertTrue(c.nativeFacts(List.of(rule("MATERIAL","乙公司","","守法承诺书",Map.of())),c.all).isEmpty());}
    @Test void visualClearAcceptsFixedAuthenticityLimitationButRejectsWrongImage(){EvidenceCorpus c=new EvidenceCorpus(List.of(doc("授权书\n甲公司盖章可见位置")));Map<String,Object> observation=linked("id","v","obligationId","r","documentId","bid","location",1,"locationType","PAGE","imageHash","image","type","SEAL","observedValue","甲公司","readability","CLEAR","sourceBbox",List.of(1,1,30,30),"source",Map.of("documentHash","sha","renderedSha256","image"),"limitations",List.of("视觉可见不能证明印章真伪"));Rule r=new Rule("r","甲公司盖章可见","VISUAL","甲公司","seal","","","",Map.of("documentType","授权书"),"盖章可见","",List.of());assertEquals("PASS",new RuleEvaluator(List.of(),c,Map.of("visualObservations",List.of(observation))).evaluate(r).status());observation.put("imageHash","foreign");assertEquals("UNDETERMINED",new RuleEvaluator(List.of(),c,Map.of("visualObservations",List.of(observation))).evaluate(r).status());}
    @Test void sealPresencePassDoesNotRequireAuthenticityCertification(){
        EvidenceCorpus c=new EvidenceCorpus(List.of(doc("授权书\n甲公司盖章位置")));
        Rule rule=new Rule("r","甲公司授权书盖章","VISUAL","甲公司","seal","","","",Map.of("documentType","授权书"),"授权书盖章","",List.of());
        Map<String,Object> observed=linked("id","v","obligationId","r","documentId","bid","location",1,"locationType","PAGE",
            "imageHash","image","type","SEAL","observedValue","甲公司","readability","CLEAR","sourceBbox",List.of(1,1,30,30),
            "source",Map.of("documentHash","sha","renderedSha256","image"),"authenticityVerified",false);
        var decision=new RuleEvaluator(List.of(),c,Map.of("visualObservations",List.of(observed))).evaluate(rule);
        assertEquals("PASS",decision.status());assertEquals("要求位置已盖章，满足盖章要求",decision.reason());
        assertEquals("UNDETERMINED",new RuleEvaluator(List.of(),c,Map.of()).evaluate(rule).status());
        observed.put("readability","UNREADABLE");assertEquals("UNDETERMINED",new RuleEvaluator(List.of(),c,Map.of("visualObservations",List.of(observed))).evaluate(rule).status());
    }
    @Test void priorRevisionCompileReuseDoesNotSpendCurrentBudget()throws Exception{ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "g";}public JsonNode request(String op,Map<String,Object> input){return json.createObjectNode();}};RunSession prior=new RunSession(gateway,Map.of(),"a");JsonNode raw=prior.model("COMPILE",Map.of("a","b"));prior.completeCompilation(Map.of("a","b"),raw,List.of());List<Map<String,Object>> copies=new ArrayList<>();for(Map<String,Object> s:prior.steps){Map<String,Object> copy=new HashMap<>(s);copy.put("paidInPriorRevision",true);copies.add(copy);}RunSession next=new RunSession(gateway,Map.of("priorSteps",copies,"maxModelCalls",1),"new-document");next.model("COMPILE",Map.of("a","b"));assertEquals(1,next.resumedSteps);assertEquals(0,next.priorCalls);next.model("EXTRACT",Map.of("new","source"));assertEquals(1,next.modelCalls);}
    @Test void projectBudgetDenialMakesNoPaidRequest(){AtomicInteger calls=new AtomicInteger();ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "g";}public JsonNode request(String op,Map<String,Object> input){calls.incrementAndGet();return json.createObjectNode();}};RunSession session=new RunSession(gateway,Map.of("modelAttemptPermit",(java.util.function.BooleanSupplier)()->false),"s");assertThrows(IOException.class,()->session.model("COMPILE",Map.of()));assertEquals(0,calls.get());}
    @Test void defaultSessionHasNoLegacyTotalCallCeiling()throws Exception{AtomicInteger calls=new AtomicInteger();ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "unbounded";}public JsonNode request(String op,Map<String,Object> input){calls.incrementAndGet();return json.createObjectNode();}};RunSession session=new RunSession(gateway,Map.of(),"s");for(int i=0;i<20;i++)session.model("EXTRACT",Map.of("packet",i));assertEquals(20,calls.get());assertEquals(20,session.modelCalls);}
    @Test void frozenClarificationCanProvideDeadlineButForeignProjectCannot(){ModelGateway gateway=new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "reference";}public JsonNode request(String op,Map<String,Object> input){if(op.equals("COMPILE"))return json.valueToTree(Map.of("logic","ALL","rules",List.of(Map.of("id","r","predicate","REFERENCE_TIME","sourceQuote","参考截止时间"))));return json.valueToTree(Map.of("facts",List.of()));}};VerificationEngine engine=new VerificationEngine(gateway,null);Document clarification=new Document("clarification","p","TENDER","澄清",2,"hash","",List.of(new Page(1,"投标截止日期：2025年9月1日","PARAGRAPH","DOCX","")),List.of());Map<String,Object> ctx=new HashMap<>(Map.of("referenceDate","2025-09-01","referenceDateSource","clarification","referenceDateEvidence",Map.of("documentId","clarification","page",1,"locationType","PARAGRAPH","quote","投标截止日期：2025年9月1日","confirmation","USER_SELECTED_VERSION"),"tenderDocuments",List.of(clarification)));assertEquals("PASS",engine.evaluate(new Checkpoint("ref","参考截止时间","参考","","SEMANTIC_RESPONSE","","","参考截止时间","",true,true,true,null),List.of(doc("投标资料")),null,ctx).get("businessDecision"));Document foreign=new Document(clarification.id(),"other","TENDER",clarification.name(),2,"hash","",clarification.pages(),List.of());ctx.put("tenderDocuments",List.of(foreign));assertEquals("UNDETERMINED",engine.evaluate(new Checkpoint("ref","参考截止时间","参考","","SEMANTIC_RESPONSE","","","参考截止时间","",true,true,true,null),List.of(doc("投标资料")),null,ctx).get("businessDecision"));}
}
